SELECT r.review_id AS reviewId, r.center_no AS centerNo, r.member_id AS memberId, r.content AS content, r.review_score AS rating, r.created_date AS createdDate, c.center_name AS centerName 
FROM review r LEFT JOIN fitness_center c ON r.center_no = c.center_no WHERE r.member_id = #{memberId}
 AND r.content LIKE CONCAT('%', #{keyword}, '%') 
ORDER BY r.created_date DESC LIMIT #{size} OFFSET #{startRow}

SELECT b.center_no AS centerNo, c.center_name AS centerName, c.facility_addr AS address, c.review_score AS rating,  b.regi_date AS bookmarkDate
FROM fitness_bookmark b JOIN fitness_center c ON b.center_no = c.center_no
WHERE b.member_id = #{memberId} ORDER BY b.regi_date DESC LIMIT #{size} OFFSET #{startRow}
